using Planner.Core;
using Planner.Data;
using Activity = Planner.Core.Activity;

var tests = new List<(string, Action)>();
void Test(string name, Action body) => tests.Add((name, body));
void Equal<T>(T expected, T actual) { if (!EqualityComparer<T>.Default.Equals(expected, actual)) throw new Exception($"expected {expected}, got {actual}"); }
void Reject(Action body) { try { body(); } catch (ArgumentException) { return; } catch (InvalidOperationException) { return; } throw new Exception("expected rejection"); }
DateTime D(int day, int hour = 0) => new(2026, 11, day, hour, 0, 0);
PlannerState Weekly()
{
    var s = new PlannerState();var t = new ScheduleTable { Id = "work", Name = "工作" };s.Tables.Add(t);
    s.Activities.Add(new Activity { Id = "a", TableId = t.Id, Title = "上班", Kind = "WEEKLY", DurationMin = 60 });
    s.Rules.Add(new RecurrenceRule { ActivityId = "a", ValidFrom = new(2026,11,1), WeekMask = 31, StartTime = "09:00" });
    return s;
}
Test("weekly rules share time and honor all weekdays", () => { var x=CalendarEngine.Expand(Weekly(),D(2),D(9));Equal(5,x.Count);Equal(9,x[0].Start.Hour); });
Test("cancelled instance does not remove whole rule", () => { var s=Weekly();s.Exceptions.Add(new() { ActivityId="a",OriginDate=new(2026,11,3),Kind="CANCEL" });Equal(4,CalendarEngine.Expand(s,D(2),D(9)).Count); });
Test("override moved into window retains original key once", () => { var s=Weekly();s.Exceptions.Add(new() { ActivityId="a",OriginDate=new(2026,11,2),StartAt=D(7,10),EndAt=D(7,11) });var x=CalendarEngine.Expand(s,D(7),D(8));Equal(1,x.Count);Equal("a:2026-11-02",x[0].Key); });
Test("override moved out of window not duplicated at origin", () => { var s=Weekly();s.Exceptions.Add(new() { ActivityId="a",OriginDate=new(2026,11,2),StartAt=D(7,10),EndAt=D(7,11) });Equal(0,CalendarEngine.Expand(s,D(2),D(3)).Count); });
Test("cross midnight preceding instance is included", () => { var s=Weekly();s.Rules[0].StartTime="23:00";s.Activities[0].DurationMin=180;Equal(1,CalendarEngine.Expand(s,D(3),D(3,1)).Count); });
Test("disabled table excluded but selection is independent", () => { var s=Weekly();s.Tables[0].Enabled=false;Equal(0,CalendarEngine.Expand(s,D(2),D(9)).Count); });
Test("touching intervals not overlap", () => { var a=Weekly().Activities[0];Equal(0,CalendarEngine.Conflicts([new(a,null,"甲",null,D(2,9),D(2,10)),new(a,new(2026,11,3),"乙",null,D(2,10),D(2,11))]).Count); });
Test("nested overlap reports all pairs", () => { var a=Weekly().Activities[0];Equal(3,CalendarEngine.Conflicts([new(a,new(2026,11,2),"甲",null,D(2,8),D(2,12)),new(a,new(2026,11,3),"乙",null,D(2,9),D(2,11)),new(a,new(2026,11,4),"丙",null,D(2,10),D(2,11))]).Count); });
Test("stale change cannot overwrite", () => { var s=Weekly();s.Revision=5;Reject(()=>ChangeService.Apply(s,[],4)); });
Test("single weekly edit preserves future repeats", () => { var s=Weekly();var a=JsonKit.Clone(s.Activities[0]);a.StartAt=D(3,11);a.EndAt=D(3,12);var n=ChangeService.Apply(s,[new(){Activity=a,OriginDate=new(2026,11,3)}],0);Equal(11,CalendarEngine.Expand(n,D(3),D(4)).Single().Start.Hour);Equal(9,CalendarEngine.Expand(n,D(4),D(5)).Single().Start.Hour); });
Test("invalid end time refused without mutating state", () => { var s=Weekly();var a=new Activity{TableId="work",Title="错误",StartAt=D(2,10),EndAt=D(2,9)};Reject(()=>ChangeService.Apply(s,[new(){Activity=a}],0));Equal(1,s.Activities.Count); });

Test("sqlite roundtrip retains recurrence and unicode", () => {
    var path=Path.Combine(Path.GetTempPath(),"planner-test-"+Guid.NewGuid()+".db");
    try {var store=new SqliteStore(path);var s=Weekly();s.Revision=1;store.Save(s,0);var read=store.Load();Equal("上班",read.Activities.Single().Title);Equal(5,CalendarEngine.Expand(read,D(2),D(9)).Count);Equal(1L,read.Revision);}finally{File.Delete(path);}
});
Test("sqlite stale write and invalid foreign key preserve saved data", () => {
    var path=Path.Combine(Path.GetTempPath(),"planner-test-"+Guid.NewGuid()+".db");
    try {var store=new SqliteStore(path);var s=Weekly();s.Revision=1;store.Save(s,0);Reject(()=>store.Save(s,0));var bad=s.Copy();bad.Revision=2;bad.Activities[0].TableId="missing";try{store.Save(bad,1);}catch(Exception){}Equal("work",store.Load().Activities.Single().TableId);Equal(1L,store.Load().Revision);}finally{File.Delete(path);}
});
Test("future rule split preserves overrides and history",()=>{var s=Weekly();s.Exceptions.Add(new(){ActivityId="a",OriginDate=new(2026,11,4),StartAt=D(7,12),EndAt=D(7,13)});var a=JsonKit.Clone(s.Activities[0]);var r=JsonKit.Clone(s.Rules[0]);r.StartTime="10:00";var n=ChangeService.Apply(s,[new(){Activity=a,Rule=r,Scope="FUTURE",SplitDate=new(2026,11,3)}],0);Equal(9,CalendarEngine.Expand(n,D(2),D(3)).Single().Start.Hour);Equal(10,CalendarEngine.Expand(n,D(3),D(4)).Single().Start.Hour);Equal(12,CalendarEngine.Expand(n,D(7),D(8)).Single().Start.Hour);});
Test("LLM scope excludes other table and private notes",()=>{var s=Weekly();s.Activities[0].Note="secret";s.Tables.Add(new(){Id="private"});s.Activities.Add(new(){Id="hidden",TableId="private",Title="私人",StartAt=D(2,8),EndAt=D(2,9)});var scope=ScopeContext.Build(s,["work"],D(2),D(3));var json=System.Text.Json.JsonSerializer.Serialize(scope,JsonKit.Options);Equal(false,json.Contains("secret"));Equal(false,json.Contains("私人"));Equal(1,scope.Items.Count);});
Test("LLM delete cannot target unselected activity",()=>{var s=Weekly();var scope=ScopeContext.Build(s,["work"],D(2),D(3));var reply=new AiReply{Operations=[new(){Action="DELETE",TargetActivityId="missing"}]};Reject(()=>DraftService.Commands(s,new(0,scope,reply),[0]));});
Test("LLM add outside authorized date rejected",()=>{var s=Weekly();var scope=ScopeContext.Build(s,["work"],D(2),D(3));var reply=new AiReply{Operations=[new(){Action="ADD",TableId="work",Title="越界",StartAt=D(4,9),EndAt=D(4,10)}]};Reject(()=>DraftService.Commands(s,new(0,scope,reply),[0]));});
Test("LLM stale draft rejected",()=>{var s=Weekly();var scope=ScopeContext.Build(s,["work"],D(2),D(3));Reject(()=>DraftService.Commands(s,new(9,scope,new()),[]));});
Test("reminder fallback to start and persisted deduplication",()=>{var s=Weekly();s.Reminders.Add(new(){ActivityId="a",Enabled=true,LeadMin=15});var due=ReminderEngine.Due(s,D(2,9),D(2,8));Equal(1,due.Count);Equal("活动开始提醒",due[0].Label);s.Deliveries.Add(new(){ActivityId="a",InstanceKey=due[0].Key,DueAt=due[0].DueAt});Equal(0,ReminderEngine.Due(s,D(2,9),D(2,8)).Count);});

Test("geofence rejects outside points and accepts interior",()=>{GeoPoint[] p=[new(0,0),new(10,0),new(10,10),new(0,10)];Equal(true,GeoBoundary.Contains(p,new(5,5)));Equal(false,GeoBoundary.Contains(p,new(12,5)));});
Test("map parser does not invent unknown driving total cost",()=>{var json="""{"status":"1","route":{"paths":[{"distance":"1000","cost":{"duration":"600","tolls":"2"},"steps":[{"instruction":"直行","polyline":"1,1;2,2"}]}]}}""";IReadOnlyList<GeoPoint>[] bounds=[new GeoPoint[]{new(0,0),new(10,0),new(10,10),new(0,10)}];var x=AmapClient.ParseRoutes(json,"CAR",bounds).Single();Equal(200,x.KnownCostFen);Equal(false,x.CostComplete);Equal(600,x.DurationSec);});
Test("map parser excludes railway transit and routes outside city",()=>{IReadOnlyList<GeoPoint>[] bounds=[new GeoPoint[]{new(0,0),new(10,0),new(10,10),new(0,10)}];var railway="""{"status":"1","route":{"transits":[{"duration":"600","segments":[{"railway":{"name":"火车"}}]}]}}""";Equal(0,AmapClient.ParseRoutes(railway,"BUS",bounds).Count);var outside="""{"status":"1","route":{"paths":[{"cost":{"duration":"500"},"steps":[{"polyline":"1,1;20,20"}]}]}}""";Equal(0,AmapClient.ParseRoutes(outside,"WALK",bounds).Count);});
Test("planner preserves fixed activity and travel constraints",()=>{var s=Weekly();s.Rules.Clear();s.Activities.Clear();var origin=new Place{Id="origin",Lng=1,Lat=1,Status="VERIFIED",Source="测试夹具"};var dest=new Place{Id="dest",Lng=2,Lat=2,Status="VERIFIED",Source="测试夹具"};s.Places.AddRange([origin,dest]);s.Activities.Add(new(){TableId="work",Title="预约",PlaceId="dest",StartAt=D(2,10),EndAt=D(2,11)});var options=new ItineraryPlanner(new TestMap()).GenerateAsync(s,new(){Date=new(2026,11,2),Origin=origin,Earliest=D(2,9),Modes=["WALK"]},default).GetAwaiter().GetResult();Equal(10,options[0].Stops[0].Start.Hour);Equal(true,options[0].Stops[0].Arrive<=D(2,10));});

Test("flexible activity cannot be stored outside its window",()=>{var s=Weekly();var a=new Activity{TableId="work",Title="灵活",ConstraintType="FLEXIBLE",StartAt=D(2,8),EndAt=D(2,9),DurationMin=60,WindowStart=D(2,10),WindowEnd=D(2,12)};Reject(()=>ChangeService.Apply(s,[new(){Activity=a}],0));});
Test("weekly rule cannot silently become once during future split",()=>{var s=Weekly();var a=JsonKit.Clone(s.Activities[0]);a.Kind="ONCE";a.StartAt=D(3,10);a.EndAt=D(3,11);Reject(()=>ChangeService.Apply(s,[new(){Activity=a,Rule=JsonKit.Clone(s.Rules[0]),Scope="FUTURE",SplitDate=new(2026,11,3)}],0));});
Test("LLM editing an override preserves its effective location",()=>{var s=Weekly();s.Places.Add(new(){Id="newplace",Name="新地点"});s.Exceptions.Add(new(){ActivityId="a",OriginDate=new(2026,11,2),StartAt=D(2,10),EndAt=D(2,11),PlaceId="newplace",PlaceOverride=true});var ctx=ScopeContext.Build(s,["work"],D(2),D(3));var draft=new ChangeDraft(0,ctx,new(){Operations=[new(){Action="UPDATE",TargetActivityId="a",OriginDate=new(2026,11,2),Title="改名"}]});var next=ChangeService.Apply(s,DraftService.Commands(s,draft,[0]),0);Equal("newplace",CalendarEngine.Expand(next,D(2),D(3)).Single().PlaceId);});
Test("boundary rejects a straight route crossing a concave exterior",()=>{IReadOnlyList<GeoPoint>[] bounds=[new GeoPoint[]{new(0,0),new(4,0),new(4,4),new(3,4),new(3,1),new(1,1),new(1,4),new(0,4)}];Equal(false,GeoBoundary.CoversSegment(bounds,new(.5,3),new(3.5,3)));});
Test("planner returns no candidate when travel misses fixed appointment",()=>{var s=Weekly();s.Rules.Clear();s.Activities.Clear();var p=new Place{Id="dest",Lng=2,Lat=2,Status="VERIFIED",Source="测试夹具"};s.Places.Add(p);s.Activities.Add(new(){TableId="work",Title="预约",PlaceId=p.Id,StartAt=D(2,9),EndAt=D(2,10)});var options=new ItineraryPlanner(new TestMap()).GenerateAsync(s,new(){Date=new(2026,11,2),Origin=new(){Lng=1,Lat=1,Status="VERIFIED",Source="测试夹具"},Earliest=D(2,9),Modes=["WALK"]},default).GetAwaiter().GetResult();Equal(0,options.Count);});
Test("route plan persists atomically with endpoints and rejects stale confirmation",()=>{var s=Weekly();s.Rules.Clear();s.Activities.Clear();var origin=new Place{Id="origin",Lng=1,Lat=1,Status="VERIFIED",Source="测试夹具"};s.Places.Add(new(){Id="dest",Lng=2,Lat=2,Status="VERIFIED",Source="测试夹具"});s.Activities.Add(new(){TableId="work",Title="预约",PlaceId="dest",StartAt=D(2,10),EndAt=D(2,11)});var req=new PlanningRequest{Date=new(2026,11,2),Origin=origin,Earliest=D(2,9),Modes=["WALK"]};var candidate=new ItineraryPlanner(new TestMap()).GenerateAsync(s,req,default).GetAwaiter().GetResult().First();var next=PlanService.Confirm(s,s,req,candidate,0);Equal(1,next.Plans.Count);Equal(1,next.Legs.Count);Equal("VALID",next.Legs[0].ValidationStatus);Reject(()=>PlanService.Confirm(next,s,req,candidate,0));var path=Path.Combine(Path.GetTempPath(),"planner-plan-"+Guid.NewGuid()+".db");try{var store=new SqliteStore(path);store.Save(next,0);Equal(1,store.Load().Segments.Count);}finally{File.Delete(path);}});

Test("malformed nullable model operations rejected before preview",()=>Reject(()=>LlmClient.ParseReply("{\"message\":null,\"operations\":null}")));
Test("missed reminder summary excludes already delivered and future reminders",()=>{var s=Weekly();s.Reminders.Add(new(){ActivityId="a",Enabled=true,LeadMin=15});Equal(1,ReminderEngine.MissedToday(s,D(2,12)).Count);Equal(0,ReminderEngine.MissedToday(s,D(2,8)).Count);});

Test("one unsupported transport keeps other route candidates",()=>{var s=Weekly();s.Rules.Clear();s.Activities.Clear();s.Places.Add(new(){Id="dest",Lng=2,Lat=2,Status="VERIFIED"});s.Activities.Add(new(){TableId="work",Title="预约",PlaceId="dest",StartAt=D(2,10),EndAt=D(2,11)});var req=new PlanningRequest{Date=new(2026,11,2),Origin=new(){Lng=1,Lat=1,Status="VERIFIED"},Earliest=D(2,9),Modes=["CAR","WALK"]};var list=new ItineraryPlanner(new PartialMap()).GenerateAsync(s,req,default).GetAwaiter().GetResult();Equal(true,list.Count>0);});

Test("plan confirmation rejects using a car left at an earlier location",()=>{var s=Weekly();s.Rules.Clear();s.Activities.Clear();var origin=new Place{Id="o",Lng=1,Lat=1,Status="VERIFIED"};var candidate=new ItineraryCandidate();for(int i=0;i<3;i++){var p=new Place{Id="p"+i,Lng=2+i,Lat=2+i,Status="VERIFIED"};s.Places.Add(p);var a=new Activity{Id="x"+i,TableId="work",PlaceId=p.Id,Title="事项",StartAt=D(2,10+i*2),EndAt=D(2,11+i*2)};s.Activities.Add(a);var occurrence=new Occurrence(a,null,a.Title,p.Id,a.StartAt.Value,a.EndAt.Value);candidate.Stops.Add(new(occurrence,occurrence.Start,occurrence.End,new(){Label=i==1?"步行":"自驾",DurationSec=600,Segments=[new(){Mode=i==1?"WALK":"CAR",DurationSec=600}]},D(2,9+i*2),D(2,9+i*2).AddMinutes(10),0));}Reject(()=>PlanService.Confirm(s,s,new(){Date=new(2026,11,2),Origin=origin,Earliest=D(2,9),Modes=["WALK","CAR"]},candidate,0));});

Test("inserting an activity invalidates a confirmed same-day route plan",()=>{var s=Weekly();s.Plans.Add(new(){Id="plan",PlanDate=new(2026,11,2)});s.Legs.Add(new(){Id="leg",PlanId="plan",ToActivityId="a",ToOriginDate=new(2026,11,2),ValidationStatus="VALID",DepartAt=D(2,8),ArriveAt=D(2,9),QueryAt=D(2,7)});var next=ChangeService.Apply(s,[new(){Activity=new(){TableId="work",Title="新增",StartAt=D(2,12),EndAt=D(2,13)}}],0);Equal("STALE",next.Plans.Single().Status);Equal("STALE",next.Legs.Single().ValidationStatus);});
Test("deleting an activity invalidates all downstream route legs",()=>{var s=Weekly();s.Activities.Add(new(){Id="b",TableId="work",Title="后续",StartAt=D(2,12),EndAt=D(2,13)});s.Plans.Add(new(){Id="plan",PlanDate=new(2026,11,2)});s.Legs.Add(new(){Id="first",PlanId="plan",ToActivityId="a",ToOriginDate=new(2026,11,2),ValidationStatus="VALID",DepartAt=D(2,8),ArriveAt=D(2,9),QueryAt=D(2,7)});s.Legs.Add(new(){Id="later",PlanId="plan",ToActivityId="b",ValidationStatus="VALID",DepartAt=D(2,8),ArriveAt=D(2,9),QueryAt=D(2,7)});var next=ChangeService.Apply(s,[new(){Action="DELETE",Activity=JsonKit.Clone(s.Activities[0])}],0);Equal("STALE",next.Plans.Single().Status);Equal("STALE",next.Legs.Single().ValidationStatus);});
Test("AI batch can edit two occurrences of one weekly activity atomically",()=>{var s=Weekly();var context=ScopeContext.Build(s,["work"],D(2),D(4));var draft=new ChangeDraft(0,context,new(){Operations=[new(){Action="UPDATE",TargetActivityId="a",OriginDate=new(2026,11,2),Title="周一改名"},new(){Action="UPDATE",TargetActivityId="a",OriginDate=new(2026,11,3),Title="周二改名"}]});var commands=DraftService.Commands(s,draft,[0,1]);var next=ChangeService.Apply(s,commands,0);Equal(2,next.Exceptions.Count);Equal("周一改名",CalendarEngine.Expand(next,D(2),D(3)).Single().Title);});

Test("disabled table remains visible but not a planning constraint",()=>{var s=Weekly();s.Tables[0].Enabled=false;Equal(1,CalendarEngine.ExpandForDisplay(s,D(2),D(3)).Count);Equal(0,CalendarEngine.Expand(s,D(2),D(3)).Count);});
Test("future split retains standalone reminder and mapped route/delivery identities",()=>{var s=Weekly();s.Reminders.Add(new(){ActivityId="a",Enabled=true,LeadMin=20});s.Exceptions.Add(new(){ActivityId="a",OriginDate=new(2026,11,4),StartAt=D(7,12),EndAt=D(7,13)});s.Deliveries.Add(new(){ActivityId="a",InstanceKey="a:2026-11-04",DueAt=D(7,12).AddMinutes(-20)});s.Plans.Add(new(){Id="plan",PlanDate=new(2026,11,7)});s.Legs.Add(new(){Id="leg",PlanId="plan",ToActivityId="a",ToOriginDate=new(2026,11,4),DepartAt=D(7,10),ArriveAt=D(7,11),QueryAt=D(1),ValidationStatus="VALID"});var a=JsonKit.Clone(s.Activities[0]);var rule=JsonKit.Clone(s.Rules[0]);rule.WeekMask=1;var n=ChangeService.Apply(s,[new(){Activity=a,Rule=rule,Scope="FUTURE",SplitDate=new(2026,11,1),ReminderEnabled=true,ReminderLeadMin=20}],0);var standalone=CalendarEngine.Expand(n,D(7),D(8)).Single();Equal(true,n.Reminders.Single(r=>r.ActivityId==standalone.Activity.Id).Enabled);Equal(standalone.Activity.Id,n.Legs.Single().ToActivityId);Equal((DateOnly?)null,n.Legs.Single().ToOriginDate);Equal(standalone.Key,n.Deliveries.Single().InstanceKey);Equal("STALE",n.Legs.Single().ValidationStatus);Equal(0,ReminderEngine.Due(n,D(7,12),D(7,11)).Count);});
Test("weekly AI preview names actual future scope weekdays table and end policy",()=>{var s=Weekly();var ctx=ScopeContext.Build(s,["work"],D(2),D(3),true);var draft=new ChangeDraft(0,ctx,new(){Operations=[new(){Action="UPDATE",TargetActivityId="a",OriginDate=new(2026,11,2),Scope="FUTURE",WeekMask=5,Title="新安排"}]});var text=DraftService.Describe(s,draft,0);Equal(true,text.Contains("周一"));Equal(true,text.Contains("周三"));Equal(true,text.Contains("不设结束日"));Equal(true,text.Contains("工作"));Equal(true,text.Contains("未来"));});
Test("metro-only selection can confirm required access walking",()=>{var s=Weekly();s.Rules.Clear();s.Activities.Clear();s.Places.Add(new(){Id="dest",Lng=2,Lat=2,Status="VERIFIED"});s.Activities.Add(new(){TableId="work",Title="预约",PlaceId="dest",StartAt=D(2,10),EndAt=D(2,11)});var req=new PlanningRequest{Date=new(2026,11,2),Origin=new(){Lng=1,Lat=1,Status="VERIFIED"},Earliest=D(2,9),Modes=["METRO"]};var options=new ItineraryPlanner(new MetroMap()).GenerateAsync(s,req,default).GetAwaiter().GetResult();Equal(true,options.Count>0);Equal(1,PlanService.Confirm(s,s,req,options[0],0).Plans.Count);});
