Test("invalid encrypted setting remains replaceable",()=>Equal("",SettingsStore.ReadForSettings("not-base64")));
Test("confirmed route retains total known fare and incomplete flag",()=>{var s=Weekly();s.Rules.Clear();s.Activities.Clear();s.Places.Add(new(){Id="dest",Lng=2,Lat=2,Status="VERIFIED",Source="测试"});var a=new Activity{Id="x",TableId="work",PlaceId="dest",Title="预约",StartAt=D(2,10),EndAt=D(2,11)};s.Activities.Add(a);var occurrence=CalendarEngine.Expand(s,D(2),D(3)).Single();var candidate=new ItineraryCandidate{Stops=[new(occurrence,D(2,10),D(2,11),new(){KnownCostFen=400,CostComplete=true,CostNote="公交票价参考",DurationSec=600,Segments=[new(){Mode="BUS",DurationSec=600}]},D(2,9),D(2,9).AddMinutes(10),0)]};var next=PlanService.Confirm(s,s,new(){Date=new(2026,11,2),Origin=new(){Lng=1,Lat=1,Status="VERIFIED",Source="测试"},Earliest=D(2,9),Modes=["BUS"]},candidate,0);Equal(400,next.Legs.Single().KnownCostFen);Equal(true,next.Legs.Single().CostComplete);var path=Path.Combine(Path.GetTempPath(),Guid.NewGuid()+".db");try{var store=new SqliteStore(path);store.Save(next,0);Equal(400,store.Load().Legs.Single().KnownCostFen);}finally{File.Delete(path);}});
Test("version one database migrates without losing existing activity",()=>{var path=Path.Combine(Path.GetTempPath(),Guid.NewGuid()+".db");try{using(var connection=new Microsoft.Data.Sqlite.SqliteConnection("Data Source="+path+";Pooling=false")){connection.Open();using var cmd=connection.CreateCommand();using var reader=new StreamReader(typeof(TestMap).Assembly.GetManifestResourceStream("Planner.Tests.Fixtures.schema-v1.sql")!);cmd.CommandText=reader.ReadToEnd();cmd.ExecuteNonQuery();cmd.CommandText="INSERT INTO schedule_table(id,name,color,enabled,version,updated_at) VALUES('work','旧表','#E5BD99',1,1,'2026-11-01T00:00:00+08:00'); INSERT INTO activity(id,table_id,title,kind,constraint_type,start_at,end_at,duration_min,version,updated_at) VALUES('old','work','旧事项','ONCE','FIXED','2026-11-02T09:00:00+08:00','2026-11-02T10:00:00+08:00',60,1,'2026-11-01T00:00:00+08:00');";cmd.ExecuteNonQuery();}var state=new SqliteStore(path).Load();Equal("旧事项",state.Activities.Single().Title);using var c=new Microsoft.Data.Sqlite.SqliteConnection("Data Source="+path+";Pooling=false");c.Open();using var q=c.CreateCommand();q.CommandText="SELECT value FROM meta WHERE key='schema_version'";Equal(2L,Convert.ToInt64(q.ExecuteScalar()));}finally{File.Delete(path);}});

Test("AI single-instance move between tables cannot be falsely previewed",()=>{var s=Weekly();s.Tables.Add(new(){Id="other",Name="个人"});var ctx=ScopeContext.Build(s,["work","other"],D(2),D(3));var draft=new ChangeDraft(0,ctx,new(){Operations=[new(){Action="UPDATE",TargetActivityId="a",OriginDate=new(2026,11,2),TableId="other",Title="转移"}]});Reject(()=>DraftService.Commands(s,draft,[0]));});
Test("Windows protected key roundtrip keeps plaintext out of saved JSON",()=>{if(!OperatingSystem.IsWindows())return;var key="only-a-local-test-value";var folder=Path.Combine(Path.GetTempPath(),"key-test-"+Guid.NewGuid());try{var store=new SettingsStore(folder);store.Save(new(){LlmKeyProtected=SettingsStore.Protect(key)});Equal(false,File.ReadAllText(Path.Combine(folder,"services.json")).Contains(key));Equal(key,SettingsStore.Unprotect(store.Load().LlmKeyProtected));}finally{File.Delete(Path.Combine(folder,"services.json"));if(Directory.Exists(folder))Directory.Delete(folder);}});
Test("LLM selected inactive table supplies its name and editable occurrences only",()=>{var s=Weekly();s.Tables[0].Enabled=false;s.Tables.Add(new(){Id="private",Name="不授权的名称"});var scope=ScopeContext.Build(s,["work"],D(2),D(3));Equal(1,scope.Items.Count);Equal("工作",scope.Tables.Single().Name);Equal(false,scope.Tables.Single().Enabled);});

BoardTests.Register(Test);
FeatureUiTests.Register(Test);
int failed=0;
foreach(var (name,body) in tests) { try {body();Console.WriteLine("PASS "+name);}catch(Exception ex){failed++;Console.WriteLine("FAIL "+name+": "+ex.Message);} }
Console.WriteLine($"RESULT {tests.Count-failed}/{tests.Count} passed");
return failed==0?0:1;

sealed class TestMap:IMapProvider
{
    public Task<List<Place>> SearchPlacesAsync(string text,CancellationToken token)=>Task.FromResult(new List<Place>());
    public Task<List<RouteOption>> RoutesAsync(Place from,Place to,string mode,DateTime depart,CancellationToken token)=>Task.FromResult(new List<RouteOption>{new(){Label="步行",DurationSec=600,DistanceM=1000,KnownCostFen=0,CostComplete=true,Segments=[new(){Mode="WALK",DurationSec=600,DistanceM=1000}]}});
}
sealed class PartialMap:IMapProvider
{
    public Task<List<Place>> SearchPlacesAsync(string text,CancellationToken token)=>Task.FromResult(new List<Place>());
    public Task<List<RouteOption>> RoutesAsync(Place from,Place to,string mode,DateTime depart,CancellationToken token)=>mode=="CAR"?throw new InvalidOperationException("驾车接口权限不足"):new TestMap().RoutesAsync(from,to,mode,depart,token);
}
sealed class MetroMap:IMapProvider
{
    public Task<List<Place>> SearchPlacesAsync(string text,CancellationToken token)=>Task.FromResult(new List<Place>());
    public Task<List<RouteOption>> RoutesAsync(Place from,Place to,string mode,DateTime depart,CancellationToken token)=>Task.FromResult(new List<RouteOption>{new(){Label="步行接驳地铁",DurationSec=600,Segments=[new(){Mode="WALK",DurationSec=120},new(){Mode="METRO",DurationSec=480}]}});
}
